<?php
namespace Tests\Feature;use App\Actions\CreateOrderAction;use App\Models\{GuestSession,Hotel,MenuItem,Order,Restaurant};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class OrderSecurityTest extends TestCase{use RefreshDatabase;public function test_order_uses_database_price_and_is_idempotent():void{$h=Hotel::create(['name'=>'H','slug'=>'h','timezone'=>'UTC','status'=>'active']);$g=GuestSession::withoutGlobalScopes()->create(['hotel_id'=>$h->id,'qr_code_id'=>$this->qr($h->id),'public_id'=>str_repeat('a',48),'expires_at'=>now()->addHour(),'status'=>'active']);$r=Restaurant::withoutGlobalScopes()->create(['hotel_id'=>$h->id,'name'=>'Dining','tax_rate'=>10,'currency'=>'INR','is_active'=>true]);$i=MenuItem::withoutGlobalScopes()->create(['hotel_id'=>$h->id,'restaurant_id'=>$r->id,'name'=>'Meal','price'=>100,'preparation_minutes'=>20,'is_available'=>true]);$action=app(CreateOrderAction::class);$payload=['restaurant_id'=>$r->id,'idempotency_key'=>'same-key','items'=>[['menu_item_id'=>$i->id,'quantity'=>2]]];$o1=$action->execute($g,$payload);$o2=$action->execute($g,$payload);$this->assertSame($o1->id,$o2->id);$this->assertSame('220.00',(string)$o1->total);$this->assertSame(1,Order::withoutGlobalScopes()->count());}private function qr(int $hotel):int{return \DB::table('qr_codes')->insertGetId(['hotel_id'=>$hotel,'public_token'=>str_repeat('q',48),'qrable_type'=>Hotel::class,'qrable_id'=>$hotel,'is_active'=>1,'created_at'=>now(),'updated_at'=>now()]);}}
